INSERT INTO question_bank (q_id, course_id, primary_kp_id, question_type, question_text, options_json, answer_text, analysis_text, difficulty, source, variant_hint)
VALUES ('Q_0514', 1, 'KP0505', '简答', '写出 SQL 片段：Student 表的 Ssex 只允许取“男”或“女”；性别为男时 Sname 不能以 Ms. 开头；SC 表的 Grade 必须在 0—100 之间。', NULL, 'Ssex CHAR(6) CHECK(Ssex IN (''男'',''女''))；表级 CHECK(Ssex=''女'' OR Sname NOT LIKE ''Ms.%'')；Grade SMALLINT CHECK(Grade>=0 AND Grade<=100)。', '前两个约束分别演示属性级 CHECK 与元组级 CHECK：Ssex 只约束单列，性别与姓名的组合约束必须放在表级 CHECK。Grade 用 AND 连接上下界，注意闭区间与 NULL 的处理由 DBMS 语义决定。', '3', '教材 P159；例 5.7/5.9', '可把“男/女”换成“1/0”再练一次。')
